  function setupRadarRealtime(){if(radarChannel)return;radarChannel=sb.channel('dana-radar-live').on('postgres_changes',{event:'INSERT',schema:'public',table:'radar_items'},async()=>{await loadRadar();toast('وصل خبر جديد إلى الرادار');if(currentView==='radar')renderRadar();if(currentView==='dashboard')renderDashboard()}).subscribe()}
  function sectionById(id){return localSections.find(x=>x.id===id)||null}
  function sectionBySlug(slug){return localSections.find(x=>x.slug===slug)||null}
  function sectionTitleForId(id){return sectionById(id)?.title||'غير مصنف'}
  function radarTier(score){return score>=85?'urgent':score>=72?'important':score>=60?'worth':score>=45?'follow':'low'}
  function radarTierLabel(tier){return {urgent:'عاجل ومهم جدًا',important:'مهم',worth:'يستحق التغطية',follow:'متابعة',low:'منخفض الأولوية'}[tier]||'متابعة'}
  function timeAgo(d){if(!d)return '—';const mins=Math.max(0,Math.round((Date.now()-new Date(d).getTime())/60000));if(mins<60)return `منذ ${mins||1} د`;const h=Math.floor(mins/60);if(h<24)return `منذ ${h} س`;return `منذ ${Math.floor(h/24)} ي`}
  function radarGroups(items=radarItems){const groups=new Map();for(const item of items){const k=item.cluster_key||item.id;if(!groups.has(k))groups.set(k,[]);groups.get(k).push(item)}return [...groups.values()].map(g=>({lead:[...g].sort((a,b)=>(b.priority_score||0)-(a.priority_score||0))[0],items:g,sources:[...new Set(g.map(x=>x.source?.name).filter(Boolean))]})).sort((a,b)=>(b.lead.priority_score||0)-(a.lead.priority_score||0)||String(b.lead.published_at||'').localeCompare(String(a.lead.published_at||'')))}

  function render(view){currentView=view;sectionLabel.textContent=sectionNames[view]||view;$$('[data-view]',nav).forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('.studio-sidebar').classList.remove('open');if(view==='dashboard')renderDashboard();if(view==='radar')renderRadar();if(view==='compose')renderCompose();if(view==='content')renderContent();if(view==='series')renderSeriesManager();if(view==='sections')renderSectionsManager();if(view==='sources')renderSourcesManager();if(view==='analytics')renderAnalytics();if(view==='settings')renderSettings()}
  async function getAnalytics(days=analyticsDays){const {data,error}=await sb.rpc('analytics_dashboard',{p_days:days});if(error)throw error;return data||{summary:{},daily:[],top_articles:[],sources:[],devices:[],searches:[],content:{}}}
  function titleForSlug(slug){const a=localArticles.find(x=>x.slug===slug)||bundledArticles.find(x=>x.slug===slug);if(a)return a.title;return slug||'—'}
  function nextSeriesOrder(id){if(!id)return 1;return Math.max(0,...localArticles.filter(a=>a.series_id===id).map(a=>Number(a.series_order)||0))+1}

  async function renderDashboard(){
    const newRadar=radarItems.filter(x=>x.status==='new'),urgent=newRadar.filter(x=>x.priority_score>=85),drafts=localArticles.filter(x=>x.status==='draft'),today=saudiDate(),publishedToday=localArticles.filter(x=>x.status==='published'&&String(x.published_date||'')===today),top=radarGroups(newRadar).slice(0,5);
    content.innerHTML=`<div class="view-head newsroom-dash-head"><div><span class="eyebrow">DANA NEWSROOM</span><h1>وش يستحق يعرفه جيلنا اليوم؟</h1><p>ابدئي من الأعلى. الأخبار مرتبة تلقائيًا حسب الأهمية، والقرار النهائي لك.</p></div><div class="head-actions"><button class="secondary-btn" id="runRadarDash">جمع الأخبار الآن ↻</button><button class="primary-btn" id="quickCompose">مادة جديدة <b>+</b></button></div></div>
    <div class="metric-grid newsroom-metrics">${metric('المواد المنشورة',n(localArticles.filter(x=>x.status==='published').length),'يتحدث تلقائيًا')}${metric('الوارد الجديد',n(newRadar.length),'في رادار الأخبار')}${metric('مهم جدًا',n(urgent.length),'أولوية 85+')}${metric('المسودات',n(drafts.length),'قيد العمل')}${metric('نُشر اليوم',n(publishedToday.length),'من لوحة دانه')}</div>
    <div class="newsroom-dashboard-grid"><section class="panel priority-panel"><div class="panel-head"><div><h2>الأهم الآن</h2><p>أعلى خمسة أحداث حسب درجة الأولوية.</p></div><button class="text-btn" id="openRadar">فتح الرادار كاملًا ←</button></div><div class="priority-stack">${top.map((g,i)=>radarMini(g,i)).join('')||'<div class="empty-state">لم تصل أخبار جديدة بعد.</div>'}</div></section><section class="panel"><div class="panel-head"><h2>سير العمل</h2><span>EDITORIAL FLOW</span></div><div class="flow-board"><button data-flow="radar"><b>${n(newRadar.length)}</b><span>وارد</span></button><button data-flow="compose"><b>${n(drafts.length)}</b><span>مسودات</span></button><button data-flow="content"><b>${n(publishedToday.length)}</b><span>منشور اليوم</span></button><button data-flow="series"><b>${n(localSeries.filter(x=>x.status==='published').length)}</b><span>سلاسل</span></button></div><div class="newsroom-note"><span>المعيار التحريري</span><strong>ليس الأكثر انتشارًا دائمًا هو الأهم.</strong><p>نرفع الخبر حين يجمع التأثير، الصلة بجيلك، حداثة المعلومة وقوة المصدر.</p></div></section></div>`;
    $('#quickCompose').onclick=()=>render('compose');$('#openRadar').onclick=()=>render('radar');$$('[data-flow]').forEach(b=>b.onclick=()=>render(b.dataset.flow));$('#runRadarDash').onclick=async e=>{e.currentTarget.disabled=true;try{const r=await radarEdge('ingest');await Promise.all([loadRadar(),loadSources()]);toast(`اكتمل الرصد · ${r.inserted||0} خبر جديد`);renderDashboard()}catch(err){toast(`تعذر الرصد: ${err.message}`)}finally{e.currentTarget.disabled=false}}
  }
  function radarMini(g,i){const x=g.lead;return `<article class="priority-mini ${radarTier(x.priority_score)}"><div class="score-orb"><b>${x.priority_score}</b><span>/100</span></div><div><span>${esc(radarTierLabel(x.priority_tier||radarTier(x.priority_score)))} · ${esc(x.source?.name||'مصدر')} · ${esc(timeAgo(x.published_at||x.fetched_at))}</span><h3>${esc(x.title)}</h3><p>${esc(x.why_youth||'')}</p>${g.items.length>1?`<small>${g.sources.length} مصادر لنفس الحدث</small>`:''}</div><button data-radar-edit="${x.id}" aria-label="ابدأ التحرير">←</button></article>`}
