    const seriesSelect=$('#articleSeries'),seriesOrderField=$('#seriesOrderField'),seriesOrderInput=$('#seriesOrder');seriesSelect?.addEventListener('change',()=>{const id=seriesSelect.value;seriesOrderField.hidden=!id;if(id&&!seriesOrderInput.value)seriesOrderInput.value=nextSeriesOrder(id)});$('#manageSeriesFromCompose')?.addEventListener('click',()=>render('series'));
    let selectedFile=null,removeExisting=false,objectUrl=null;const input=$('#articleImage'),drop=$('#imageDrop'),preview=$('#imagePreview'),remove=$('#removeImage');function setPreview(file){if(!file)return;if(!/^image\/(jpeg|png|webp|gif)$/.test(file.type)){toast('اختاري ملف صورة JPG أو PNG أو WEBP أو GIF');return}if(file.size>10*1024*1024){toast('حجم الصورة أكبر من 10MB');return}selectedFile=file;removeExisting=false;if(objectUrl)URL.revokeObjectURL(objectUrl);objectUrl=URL.createObjectURL(file);preview.innerHTML=`<img src="${objectUrl}" alt="معاينة الصورة">`;drop.classList.add('has-image');remove.hidden=false}input.addEventListener('change',e=>setPreview(e.target.files?.[0]));$('#chooseImage').addEventListener('click',e=>{e.stopPropagation();input.click()});drop.addEventListener('click',()=>input.click());drop.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();input.click()}});['dragenter','dragover'].forEach(ev=>drop.addEventListener(ev,e=>{e.preventDefault();drop.classList.add('dragging')}));['dragleave','drop'].forEach(ev=>drop.addEventListener(ev,e=>{e.preventDefault();drop.classList.remove('dragging')}));drop.addEventListener('drop',e=>setPreview(e.dataTransfer?.files?.[0]));remove.addEventListener('click',e=>{e.stopPropagation();selectedFile=null;removeExisting=true;input.value='';preview.innerHTML='<span class="upload-icon">＋</span>';drop.classList.remove('has-image');remove.hidden=true});let submitAction='publish';$$('#articleForm button[type="submit"]').forEach(b=>b.addEventListener('click',()=>submitAction=b.dataset.action));$('#articleForm').addEventListener('submit',e=>saveArticle(e,submitAction,selectedFile,article,removeExisting,radar));
